from fractions import Fraction
import math

def lcm(a, b):
    from math import gcd
    return a // gcd(a, b) * b

def squarefree_multiplier(n):
    if n == 0:
        return 1
    m = n
    s = 1
    d = 2
    while d * d <= m:
        cnt = 0
        while m % d == 0:
            m //= d
            cnt += 1
        if cnt % 2 == 1:
            s *= d
        d += 1
    if m > 1:
        s *= m
    return s

def verifier(assign):
    # Basic key checks
    required = ['r_sum','e_const','f_const','p_coeff','q_str','s_num','s_den','t_num','t_den','k_expected']
    for k in required:
        if k not in assign:
            # Missing key; invalid instance
            return (False, None)
    r_sum = assign['r_sum']
    e_const = assign['e_const']
    f_const = assign['f_const']
    p_coeff = assign['p_coeff']
    # parse Q string
    try:
        q_str = assign['q_str']
        if isinstance(q_str, str) and '/' in q_str:
            num_str, den_str = q_str.split('/')
            Q = Fraction(int(num_str), int(den_str))
        else:
            Q = Fraction(assign['q_str'])
    except Exception:
        # Invalid Q
        return (False, None)
    p_num = assign['s_num']
    p_den = assign['s_den']
    t_num = assign['t_num']
    t_den = assign['t_den']
    # reconstruct s,t,x,y
    s = Fraction(p_num, p_den)
    t = Fraction(t_num, t_den)
    x = Fraction(1, 2) - Fraction(s*s, 2)
    y = Fraction(1, 2) - Fraction(t*t, 2)
    # domain checks
    if not (Fraction(0,1) < x < Fraction(1,2) and Fraction(0,1) < y < Fraction(1,2)):
        return (False, None)
    D = Fraction(e_const, 1) - Fraction(f_const, 1) * x - s
    if D == 0:
        return (False, None)
    # validate identity numerically
    xf = float(x)
    r = float(r_sum)
    Aterm = (r**3 + r * (xf**2)) / 2.0
    Bterm = (r**3 + r * (xf**2))**2 - (4.0 * (xf**6)) / 27.0
    if Bterm <= 0:
        return (False, None)
    cr1 = (Aterm + math.sqrt(Bterm) / 6.0) ** (1.0/3.0)
    cr2 = (Aterm - math.sqrt(Bterm) / 6.0) ** (1.0/3.0)
    cube_sum = cr1 + cr2
    LHS = r + float(t)
    RHS_fraction = float((p_coeff * x + Q + 2 * s) / D)
    RHS = float(y) + RHS_fraction + cube_sum
    if not (abs(LHS - RHS) < 1e-7):
        return (False, None)
    # compute k
    den_x = x.denominator
    den_y = y.denominator
    from math import gcd
    L = (den_x // gcd(den_x, den_y)) * den_y
    I_int = (x + y) * L
    if I_int.denominator != 1:
        return (False, None)
    I_int = I_int.numerator
    s_extra = squarefree_multiplier(I_int)
    k_val = L * s_extra
    # enforce difficulty
    if k_val < 150:
        return (False, None)
    # sanity check with expected (from generator)
    if 'k_expected' in assign:
        if assign['k_expected'] != k_val:
            # mismatch indicates generator/verifier disagreement
            return (False, None)
    answer = k_val
    return (True, answer)
